class Solution
{
    vector< string>build(int n, int total)
    {
        if (n == 0) return { "" };
        if (n == 1) return { "0", "1", "8" };
        vector< string>out;
        for (auto&mid : build(n - 2, total))
        {
            for (auto p : vector< string> { "00", "11", "69", "88", "96" })
            {
                if (n == total && p == "00")
                {
                    continue;
                }
                out.push_back(p.substr(0, 1) + mid + p.substr(1, 1));
            }
        }
        return out;
    }
public:
    vector< string>findStrobogrammatic(int n)
    {
        return build(n, n);
    }
};
